602	mod datetime {
603	    use std::fmt::{self, Formatter, Write};
604	
605	    pub fn datetime(f: &mut Formatter, datetime: time::PrimitiveDateTime) -> fmt::Result {
606	        // https://html.spec.whatwg.org/#valid-global-date-and-time-string
607	        date(f, datetime.date())?;
608	        f.write_char('T')?;
609	        time(f, datetime.time())
610	    }
611	
612	    pub fn date(f: &mut Formatter, date: time::Date) -> fmt::Result {
613	        // https://html.spec.whatwg.org/#valid-date-string
614	        write!(f, "{:04}-{:02}-{:02}", date.year(), date.month() as u8, date.day())
615	    }
616	
617	    pub fn time(f: &mut Formatter, time: time::Time) -> fmt::Result {
618	        // https://html.spec.whatwg.org/#valid-time-string
619	        write!(f, "{:02}:{:02}", time.hour(), time.minute())?;
620	        if time.second() > 0 {
621	            write!(f, ":{:02}", time.second())?;
622	        }
623	        Ok(())
624	    }
625	}
