671	/// <https://html.spec.whatwg.org/#image-candidate-string>
672	pub struct ImageCandidate(EcoString);
673	
674	cast! {
675	    ImageCandidate,
676	    mut v: Dict => {
677	        let src = v.take("src")?.cast::<EcoString>()?;
678	        let width: Option<NonZeroU64> =
679	            v.take("width").ok().map(Value::cast).transpose()?;
680	        let density: Option<PositiveF64> =
681	            v.take("density").ok().map(Value::cast).transpose()?;
682	        v.finish(&["src", "width", "density"])?;
683	
684	        if src.is_empty() {
685	            bail!("`src` must not be empty");
686	        } else if src.starts_with(',') || src.ends_with(',') {
687	            bail!("`src` must not start or end with a comma");
688	        }
689	
690	        let mut out = src;
691	        match (width, density) {
692	            (None, None) => {}
693	            (Some(width), None) => write!(out, " {width}w").unwrap(),
694	            (None, Some(density)) => write!(out, " {}d", density.get()).unwrap(),
695	            (Some(_), Some(_)) => bail!("cannot specify both `width` and `density`"),
696	        }
697	
698	        Self(out)
699	    },
700	}
701	
702	impl IntoAttr for ImageCandidate {
703	    fn into_attr(self) -> EcoString {
704	        self.0
705	    }
706	}
707	
708	/// <https://html.spec.whatwg.org/multipage/images.html#valid-source-size-list>
709	pub struct SourceSize(EcoString);
710	
711	cast! {
712	    SourceSize,
713	    mut v: Dict => {
714	        let condition = v.take("condition")?.cast::<EcoString>()?;
715	        let size = v
716	            .take("size")?
717	            .cast::<Length>()
718	            .hint("CSS lengths that are not expressible as Typst lengths are not yet supported")
719	            .hint("you can use `html.elem` to create a raw attribute")?;
720	        Self(eco_format!("({condition}) {}", size.to_css(())))
721	    },
722	}
723	
724	impl IntoAttr for SourceSize {
725	    fn into_attr(self) -> EcoString {
726	        self.0
727	    }
728	}
