33	/// Creates the module with all HTML definitions.
34	pub fn module() -> Module {
35	    let mut html = Scope::deduplicating();
36	    html.start_category(Category::Html);
37	    html.define_elem::<HtmlElem>();
38	    html.define_elem::<FrameElem>();
